module rearrange_to_divisible_by_7(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] input_digits [0:15],\n    input wire [3:0] input_length,\n    output reg [3:0] output_digits [0:15],\n    output reg done\n);\n\n    // State definitions\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] COUNT = 3'd1;\n    localparam [2:0] DECREMENT = 3'd2;\n    localparam [2:0] CALCULATE_MOD = 3'd3;\n    localparam [2:0] LOOKUP = 3'd4;\n    localparam [2:0] OUTPUT = 3'd5;\n\n    reg [2:0] state, next_state;\n    reg [4:0] count [0:9];\n    reg [2:0] mod_result;\n    reg [3:0] digit_counter;\n    reg [3:0] output_index;\n    reg [15:0] current_perm;\n    reg [3:0] perm_digit;\n    reg [3:0] perm_index;\n\n    // Permutation table: for each possible modulo result (0-6), store 4-digit permutation\n    reg [15:0] perm_table [0:6];\n    integer i;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            digit_counter <= 4'd0;\n            output_index <= 4'd0;\n            mod_result <= 3'd0;\n            current_perm <= 16'd0;\n            perm_digit <= 4'd0;\n            perm_index <= 4'd0;\n            // Reset counts\n            for (i = 0; i < 10; i = i + 1) begin\n                count[i] <= 5'd0;\n            end\n            // Reset output\n            for (i = 0; i < 16; i = i + 1) begin\n                output_digits[i] <= 4'd0;\n            end\n        end else begin\n            state <= next_state;\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        // Reset counters\n                        for (i = 0; i < 10; i = i + 1) begin\n                            count[i] <= 5'd0;\n                        end\n                        digit_counter <= 4'd0;\n                        mod_result <= 3'd0;\n                        current_perm <= 16'd0;\n                        perm_digit <= 4'd0;\n                        perm_index <= 4'd0;\n                    end\n                end\n                COUNT: begin\n                    if (digit_counter < input_length) begin\n                        count[input_digits[digit_counter]] <= count[input_digits[digit_counter]] + 5'd1;\n                        digit_counter <= digit_counter + 4'd1;\n                    end\n                end\n                DECREMENT: begin\n                    count[1] <= count[1] - 5'd1;\n                    count[6] <= count[6] - 5'd1;\n                    count[8] <= count[8] - 5'd1;\n                    count[9] <= count[9] - 5'd1;\n                    digit_counter <= 4'd0;\n                end\n                CALCULATE_MOD: begin\n                    if (digit_counter < 10) begin\n                        if (count[digit_counter] > 5'd0) begin\n                            mod_result <= (mod_result * 10 + digit_counter) % 7;\n                            count[digit_counter] <= count[digit_counter] - 5'd1;\n                        end else begin\n                            digit_counter <= digit_counter + 4'd1;\n                        end\n                    end\n                end\n                LOOKUP: begin\n                    // Initialize permutation table\n                    perm_table[0] = 16'h1869; // 1869\n                    perm_table[1] = 16'h1896; // 1896\n                    perm_table[2] = 16'h1986; // 1986\n                    perm_table[3] = 16'h1698; // 1698\n                    perm_table[4] = 16'h6198; // 6198\n                    perm_table[5] = 16'h1689; // 1689\n                    perm_table[6] = 16'h1968; // 1968\n                    current_perm <= perm_table[mod_result];\n                    output_index <= 4'd0;\n                    digit_counter <= 4'd1;\n                    perm_digit <= 4'd0;\n                    perm_index <= 4'd0;\n                end\n                OUTPUT: begin\n                    if (output_index < input_length) begin\n                        if (perm_index < 4) begin\n                            output_digits[output_index] <= current_perm[15 - (perm_index * 4):12 - (perm_index * 4)];\n                            output_index <= output_index + 4'd1;\n                            perm_index <= perm_index + 4'd1;\n                        end else if (digit_counter <= 9 && digit_counter != 0) begin\n                            if (count[digit_counter] > 5'd0) begin\n                                output_digits[output_index] <= digit_counter;\n                                output_index <= output_index + 4'd1;\n                                count[digit_counter] <= count[digit_counter] - 5'd1;\n                            end else begin\n                                digit_counter <= digit_counter + 4'd1;\n                            end\n                        end else if (digit_counter == 10) begin\n                            if (count[0] > 5'd0) begin\n                                output_digits[output_index] <= 4'd0;\n                                output_index <= output_index + 4'd1;\n                                count[0] <= count[0] - 5'd1;\n                            end else begin\n                                done <= 1'b1;\n                            end\n                        end\n                    end else begin\n                        done <= 1'b1;\n                    end\n                end\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\n    always @(*) begin\n        case (state)\n            IDLE: next_state = start ? COUNT : IDLE;\n            COUNT: next_state = (digit_counter >= input_length) ? DECREMENT : COUNT;\n            DECREMENT: next_state = CALCULATE_MOD;\n            CALCULATE_MOD: begin\n                if (digit_counter >= 10) next_state = LOOKUP;\n                else if (count[digit_counter] > 5'd0) next_state = CALCULATE_MOD;\n                else next_state = CALCULATE_MOD;\n            end\n            LOOKUP: next_state = OUTPUT;\n            OUTPUT: begin\n                if (done) next_state = IDLE;\n                else next_state = OUTPUT;\n            end\n            default: next_state = IDLE;\n        endcase\n    end\n\nendmodule